// "Practise forgotten words": after a quiz/review the web app sends the words
// the user got wrong. Each word gets 3 example sentences (generated by AI in a
// single request and kept for next time); the user translates them and reads
// them aloud, then all translations are checked in a single AI request.

const (
	practiceMaxWords   = 10
	practicePerRound   = 3 // sentences shown per word
	practicePoolSize   = 6 // sentences kept per card; rounds alternate between the two halves
	practiceMaxGrading = 30
)

type practiceExample struct {
	ID int64  `json:"id"`
	En string `json:"en"`
	Vi string `json:"vi"`
}

type practiceWord struct {
	CardID    int64             `json:"card_id"`
	Word      string            `json:"word"`
	IPA       string            `json:"ipa,omitempty"`
	MeaningVi string            `json:"meaning_vi"`
	Examples  []practiceExample `json:"examples"`
}

// PracticeExamples: POST /api/practice/examples {"card_ids":[1,2,3]}
func (h *Handler) PracticeExamples(c *gin.Context) {
	var req struct {
		CardIDs []int64 `json:"card_ids" binding:"required,min=1"`
	}
	if err := c.ShouldBindJSON(&req); err != nil {
		bad(c, err)
		return
	}
	ids := uniqueIDs(req.CardIDs, practiceMaxWords)
	var cards []models.Card
	if err := h.DB.Where("id IN ? AND kind IN ?", ids, []string{models.KindVocab, models.KindPhrasal}).Find(&cards).Error; err != nil {
		internal(c, err)
		return
	}
	// keep the order the client sent
	byID := map[int64]models.Card{}
	for _, cd := range cards {
		byID[cd.ID] = cd
	}
	cards = cards[:0]
	for _, id := range ids {
		if cd, ok := byID[id]; ok {
			cards = append(cards, cd)
		}
	}
	if len(cards) == 0 {
		abort(c, http.StatusBadRequest, "no English words to practise")
		return
	}
	uid := userID(c)

	pools, err := h.examplePools(cards)
	if err != nil {
		internal(c, err)
		return
	}
	rounds := map[int64]int{}
	var rr []struct {
		CardID int64
		Round  int
	}
	h.DB.Raw(`SELECT card_id, round FROM practice_rounds WHERE user_id = ? AND card_id IN ?`, uid, ids).Scan(&rr)
	for _, r := range rr {
		rounds[r.CardID] = r.Round
	}

	// one AI request for every word that needs more sentences this round
	warning := ""
	var need []models.Card
	for _, cd := range cards {
		want := practicePerRound * (rounds[cd.ID]%2 + 1) // round 0: 3, round 1: 6, round 2: 3...
		if countAI(pools[cd.ID]) < want {
			need = append(need, cd)
		}
	}
	if len(need) > 0 {
		if !h.AI.Enabled() {
			warning = "AI is not configured on the server: using the cards' own examples."
		} else if err := h.generateExamples(c.Request.Context(), need); err != nil {
			log.Printf("[ai] practice examples: %v", err)
			warning = "AI could not write new sentences right now: using the examples we have."
		}
		if pools, err = h.examplePools(cards); err != nil {
			internal(c, err)
			return
		}
	}

	out := make([]practiceWord, 0, len(cards))
	for _, cd := range cards {
		cc := content.ToCompact(cd)
		pool := pools[cd.ID]
		if len(pool) == 0 && cc.ExampleEn != "" {
			// last resort: the card's own example sentence
			ex := models.CardExample{CardID: cd.ID, SentenceEn: cc.ExampleEn, TranslationVi: cc.ExampleVi, Source: "card"}
			h.DB.Clauses(clause.OnConflict{DoNothing: true}).Create(&ex)
			if ex.ID != 0 {
				pool = []models.CardExample{ex}
			}
		}
		pw := practiceWord{CardID: cd.ID, Word: cd.Front, IPA: cc.IPA, MeaningVi: cc.MeaningVi, Examples: []practiceExample{}}
		for _, ex := range pickRound(pool, rounds[cd.ID]) {
			pw.Examples = append(pw.Examples, practiceExample{ID: ex.ID, En: ex.SentenceEn, Vi: ex.TranslationVi})
		}
		if len(pw.Examples) == 0 {
			continue
		}
		out = append(out, pw)
		h.DB.Exec(`INSERT INTO practice_rounds (user_id, card_id, round) VALUES (?, ?, 1)
			ON CONFLICT (user_id, card_id) DO UPDATE SET round = practice_rounds.round + 1, updated_at = NOW()`, uid, cd.ID)
	}
	c.JSON(http.StatusOK, gin.H{"words": out, "warning": warning})
}

// examplePools loads the stored sentences of the cards (oldest first). The
// AI-written ones come first; the card's own example is only a fallback.
func (h *Handler) examplePools(cards []models.Card) (map[int64][]models.CardExample, error) {
	ids := make([]int64, len(cards))
	for i, cd := range cards {
		ids[i] = cd.ID
	}
	var exs []models.CardExample
	if err := h.DB.Where("card_id IN ?", ids).Order("(source = 'card'), id").Find(&exs).Error; err != nil {
		return nil, err
	}
	pools := map[int64][]models.CardExample{}
	for _, ex := range exs {
		pools[ex.CardID] = append(pools[ex.CardID], ex)
	}
	return pools, nil
}

func countAI(pool []models.CardExample) int {
	n := 0
	for _, ex := range pool {
		if ex.Source == "ai" {
			n++
		}
	}
	return n
}

// pickRound returns the sentences for this round: the first 3 on even rounds,
// the next 3 on odd rounds (when there are enough), so the learner meets new
// sentences when the same word is forgotten again.
func pickRound(pool []models.CardExample, round int) []models.CardExample {
	var ai, own []models.CardExample
	for _, ex := range pool {
		if ex.Source == "ai" {
			ai = append(ai, ex)
		} else {
			own = append(own, ex)
		}
	}
	if len(ai) == 0 {
		return own
	}
	if len(ai) > practicePoolSize {
		ai = ai[:practicePoolSize]
	}
	start := (round % 2) * practicePerRound
	if start+practicePerRound > len(ai) {
		start = max(0, len(ai)-practicePerRound)
	}
	end := min(len(ai), start+practicePerRound)
	return ai[start:end]
}

func (h *Handler) generateExamples(ctx context.Context, cards []models.Card) error {
	ctx, cancel := context.WithTimeout(ctx, 150*time.Second)
	defer cancel()
	words := make([]ai.PracticeWord, len(cards))
	for i, cd := range cards {
		cc := content.ToCompact(cd)
		meaning := cc.MeaningVi
		if meaning == "" {
			meaning = cc.MeaningEn
		}
		words[i] = ai.PracticeWord{Word: cd.Front, MeaningVi: meaning, POS: cc.POS}
	}
	res, err := h.AI.GeneratePracticeSentences(ctx, words, practicePerRound)
	if err != nil {
		return err
	}
	for _, cd := range cards {
		for _, s := range res[strings.ToLower(cd.Front)] {
			ex := models.CardExample{CardID: cd.ID, SentenceEn: s.En, TranslationVi: s.Vi, Source: "ai"}
			if err := h.DB.Clauses(clause.OnConflict{DoNothing: true}).Create(&ex).Error; err != nil {
				return err
			}
		}
	}
	return nil
}

// PracticeGrade: POST /api/practice/grade {"items":[{"example_id":1,"translation":"..."}]}
// Checks all translations of a practice session in a single AI request.
func (h *Handler) PracticeGrade(c *gin.Context) {
	if !h.AI.Enabled() {
		abort(c, http.StatusServiceUnavailable, ai.ErrNotConfigured.Error())
		return
	}
	var req struct {
		Items []struct {
			ExampleID   int64  `json:"example_id"`
			Translation string `json:"translation"`
		} `json:"items" binding:"required,min=1"`
	}
	if err := c.ShouldBindJSON(&req); err != nil {
		bad(c, err)
		return
	}
	if len(req.Items) > practiceMaxGrading {
		req.Items = req.Items[:practiceMaxGrading]
	}
	ids := make([]int64, 0, len(req.Items))
	for _, it := range req.Items {
		ids = append(ids, it.ExampleID)
	}
	var exs []models.CardExample
	if err := h.DB.Where("id IN ?", ids).Find(&exs).Error; err != nil {
		internal(c, err)
		return
	}
	exByID := map[int64]models.CardExample{}
	cardIDs := []int64{}
	for _, ex := range exs {
		exByID[ex.ID] = ex
		cardIDs = append(cardIDs, ex.CardID)
	}
	var cards []models.Card
	h.DB.Where("id IN ?", cardIDs).Find(&cards)
	cardByID := map[int64]models.Card{}
	for _, cd := range cards {
		cardByID[cd.ID] = cd
	}

	type result struct {
		ExampleID int64 `json:"example_id"`
		ai.TranslationResult
		Graded bool `json:"graded"`
	}
	results := make([]result, len(req.Items))
	var items []ai.TranslationItem
	var slots []int // results index of each item sent to AI
	for i, it := range req.Items {
		results[i].ExampleID = it.ExampleID
		ex, ok := exByID[it.ExampleID]
		tr := strings.TrimSpace(it.Translation)
		if !ok || tr == "" {
			continue
		}
		if len([]rune(tr)) > 500 {
			tr = string([]rune(tr)[:500])
		}
		cc := content.ToCompact(cardByID[ex.CardID])
		items = append(items, ai.TranslationItem{
			Word: cardByID[ex.CardID].Front, MeaningVi: cc.MeaningVi,
			SentenceEn: ex.SentenceEn, ReferenceVi: ex.TranslationVi, LearnerVi: tr,
		})
		slots = append(slots, i)
	}
	if len(items) == 0 {
		c.JSON(http.StatusOK, gin.H{"results": results})
		return
	}
	ctx, cancel := context.WithTimeout(c.Request.Context(), 150*time.Second)
	defer cancel()
	graded, err := h.AI.GradeTranslations(ctx, items)
	if err != nil {
		log.Printf("[ai] practice grade: %v", err)
		abort(c, http.StatusBadGateway, "AI could not check the translations right now, please try again")
		return
	}
	for k, g := range graded {
		if g.Score < 0 {
			continue
		}
		results[slots[k]].TranslationResult = g
		results[slots[k]].Graded = true
	}
	c.JSON(http.StatusOK, gin.H{"results": results})
}

// PracticeForgotten: GET /api/practice/forgotten
// English words the user graded "Again" today (review or due-card quiz) and has
// not practised since. Used by the Practice page and the forgotten-words drill.
func (h *Handler) PracticeForgotten(c *gin.Context) {
	uid := userID(c)
	var u models.User
	if err := h.DB.Select("id, timezone").First(&u, uid).Error; err != nil {
		internal(c, err)
		return
	}
	loc := study.UserLocation(u.Timezone)
	now := time.Now().In(loc)
	today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, loc)

	type word struct {
		ID    int64  `json:"id"`
		Front string `json:"front"`
	}
	words := []word{}
	err := h.DB.Raw(`
		SELECT c.id, c.front
		FROM review_logs r
		JOIN cards c ON c.id = r.card_id
		LEFT JOIN practice_rounds p ON p.user_id = r.user_id AND p.card_id = c.id
		WHERE r.user_id = ? AND r.rating = 1 AND r.reviewed_at >= ? AND c.kind IN ?
		GROUP BY c.id, c.front, p.updated_at
		HAVING p.updated_at IS NULL OR p.updated_at < MAX(r.reviewed_at)
		ORDER BY MAX(r.reviewed_at) DESC
		LIMIT 30`, uid, today.UTC(), []string{models.KindVocab, models.KindPhrasal}).Scan(&words).Error
	if err != nil {
		internal(c, err)
		return
	}
	c.JSON(http.StatusOK, words)
}

func uniqueIDs(in []int64, limit int) []int64 {
	seen := map[int64]bool{}
	out := []int64{}
	for _, id := range in {
		if id > 0 && !seen[id] {
			seen[id] = true
			out = append(out, id)
			if len(out) == limit {
				break
			}
		}
	}
	return out
}
